  1275  static readstat_error_t sav_parse_records_pass1(sav_ctx_t *ctx) {
  1276      char data_buf[4096];
  1277      readstat_error_t retval = READSTAT_OK;
  1278      readstat_io_t *io = ctx->io;
  1279      while (1) {
  1280          uint32_t rec_type;
  1281          uint32_t extra_info[3];
  1282          size_t data_len = 0;
  1283          int i;
  1284          int done = 0;
  1285          if (io->read(&rec_type, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
  1286              retval = READSTAT_ERROR_READ;
  1287              goto cleanup;
  1288          }
  1289
  1290          if (ctx->bswap) {
  1291              rec_type = byteswap4(rec_type);
  1292          }
  1293
  1294          switch (rec_type) {
  1295              case SAV_RECORD_TYPE_VARIABLE:
  1296                  retval = sav_skip_variable_record(ctx);
  1297                  if (retval != READSTAT_OK)
  1298                      goto cleanup;
  1299                  break;
  1300              case SAV_RECORD_TYPE_VALUE_LABEL:
  1301                  retval = sav_skip_value_label_record(ctx);
  1302                  if (retval != READSTAT_OK)
  1303                      goto cleanup;
  1304                  break;
  1305              case SAV_RECORD_TYPE_DOCUMENT:
  1306                  retval = sav_skip_document_record(ctx);
  1307                  if (retval != READSTAT_OK)
  1308                      goto cleanup;
  1309                  break;
  1310              case SAV_RECORD_TYPE_DICT_TERMINATION:
  1311                  done = 1;
  1312                  break;
  1313              case SAV_RECORD_TYPE_HAS_DATA:
  1314                  if (io->read(extra_info, sizeof(extra_info), io->io_ctx) < sizeof(extra_info)) {
  1315                      retval = READSTAT_ERROR_READ;
  1316                      goto cleanup;
  1317                  }
  1318                  if (ctx->bswap) {
  1319                      for (i=0; i<3; i++)
  1320                          extra_info[i] = byteswap4(extra_info[i]);
  1321                  }
  1322                  uint32_t subtype = extra_info[0];
  1323                  size_t size = extra_info[1];
  1324                  size_t count = extra_info[2];
  1325                  data_len = size * count;
  1326                  if (subtype == SAV_RECORD_SUBTYPE_INTEGER_INFO) {
  1327                      if (data_len > sizeof(data_buf)) {
  1328                          retval = READSTAT_ERROR_PARSE;
  1329                          goto cleanup;
  1330                      }
  1331                      if (io->read(data_buf, data_len, io->io_ctx) < data_len) {
  1332                          retval = READSTAT_ERROR_PARSE;
  1333                          goto cleanup;
  1334                      }
  1335                      retval = sav_parse_machine_integer_info_record(data_buf, data_len, ctx);
  1336                      if (retval != READSTAT_OK)
  1337                          goto cleanup;
  1338                  } else {
  1339                      if (io->seek(data_len, READSTAT_SEEK_CUR, io->io_ctx) == -1) {
  1340                          retval = READSTAT_ERROR_SEEK;
  1341                          goto cleanup;
  1342                      }
  1343                  }
  1344                  break;
  1345              default:
  1346                  retval = READSTAT_ERROR_PARSE;
  1347                  goto cleanup;
  1348                  break;
  1349          }
  1350          if (done)
  1351              break;
  1352      }
  1353  cleanup:
  1354      return retval;
  1355  }
