  1357  static readstat_error_t sav_parse_records_pass2(sav_ctx_t *ctx) {
  1358      void *data_buf = NULL;
  1359      size_t data_buf_capacity = 4096;
  1360      readstat_error_t retval = READSTAT_OK;
  1361      readstat_io_t *io = ctx->io;
  1362
  1363      if ((data_buf = readstat_malloc(data_buf_capacity)) == NULL) {
  1364          retval = READSTAT_ERROR_MALLOC;
  1365          goto cleanup;
  1366      }
  1367
  1368      while (1) {
  1369          uint32_t rec_type;
  1370          uint32_t extra_info[3];
  1371          size_t data_len = 0;
  1372          int i;
  1373          int done = 0;
  1374          if (io->read(&rec_type, sizeof(uint32_t), io->io_ctx) < sizeof(uint32_t)) {
  1375              retval = READSTAT_ERROR_READ;
  1376              goto cleanup;
  1377          }
  1378
  1379          if (ctx->bswap) {
  1380              rec_type = byteswap4(rec_type);
  1381          }
  1382
  1383          switch (rec_type) {
  1384              case SAV_RECORD_TYPE_VARIABLE:
  1385                  if ((retval = sav_read_variable_record(ctx)) != READSTAT_OK)
  1386                      goto cleanup;
  1387                  break;
  1388              case SAV_RECORD_TYPE_VALUE_LABEL:
  1389                  if ((retval = sav_read_value_label_record(ctx)) != READSTAT_OK)
  1390                      goto cleanup;
  1391                  break;
  1392              case SAV_RECORD_TYPE_DOCUMENT:
  1393                  if ((retval = sav_read_document_record(ctx)) != READSTAT_OK)
  1394                      goto cleanup;
  1395                  break;
  1396              case SAV_RECORD_TYPE_DICT_TERMINATION:
  1397                  if ((retval = sav_read_dictionary_termination_record(ctx)) != READSTAT_OK)
  1398                      goto cleanup;
  1399                  done = 1;
  1400                  break;
  1401              case SAV_RECORD_TYPE_HAS_DATA:
  1402                  if (io->read(extra_info, sizeof(extra_info), io->io_ctx) < sizeof(extra_info)) {
  1403                      retval = READSTAT_ERROR_READ;
  1404                      goto cleanup;
  1405                  }
  1406                  if (ctx->bswap) {
  1407                      for (i=0; i<3; i++)
  1408                          extra_info[i] = byteswap4(extra_info[i]);
  1409                  }
  1410                  uint32_t subtype = extra_info[0];
  1411                  size_t size = extra_info[1];
  1412                  size_t count = extra_info[2];
  1413                  data_len = size * count;
  1414                  if (data_buf_capacity < data_len) {
  1415                      if ((data_buf = readstat_realloc(data_buf, data_buf_capacity = data_len)) == NULL) {
  1416                          retval = READSTAT_ERROR_MALLOC;
  1417                          goto cleanup;
  1418                      }
  1419                  }
  1420                  if (data_len == 0 || io->read(data_buf, data_len, io->io_ctx) < data_len) {
  1421                      retval = READSTAT_ERROR_PARSE;
  1422                      goto cleanup;
  1423                  }
  1424
  1425                  switch (subtype) {
  1426                      case SAV_RECORD_SUBTYPE_INTEGER_INFO:
  1427                          /* parsed in pass 1 */
  1428                          break;
  1429                      case SAV_RECORD_SUBTYPE_FP_INFO:
  1430                          retval = sav_parse_machine_floating_point_record(data_buf, size, count, ctx);
  1431                          if (retval != READSTAT_OK)
  1432                              goto cleanup;
  1433                          break;
  1434                      case SAV_RECORD_SUBTYPE_VAR_DISPLAY:
  1435                          retval = sav_store_variable_display_parameter_record(data_buf, size, count, ctx);
  1436                          if (retval != READSTAT_OK)
  1437                              goto cleanup;
  1438                          break;
  1439                      case SAV_RECORD_SUBTYPE_LONG_VAR_NAME:
  1440                          retval = sav_parse_long_variable_names_record(data_buf, count, ctx);
  1441                          if (retval != READSTAT_OK)
  1442                              goto cleanup;
  1443                          break;
  1444                      case SAV_RECORD_SUBTYPE_VERY_LONG_STR:
  1445                          retval = sav_parse_very_long_string_record(data_buf, count, ctx);
  1446                          if (retval != READSTAT_OK)
  1447                              goto cleanup;
  1448                          break;
  1449                      case SAV_RECORD_SUBTYPE_LONG_STRING_VALUE_LABELS:
  1450                          retval = sav_parse_long_string_value_labels_record(data_buf, size, count, ctx);
  1451                          if (retval != READSTAT_OK)
  1452                              goto cleanup;
  1453                          break;
  1454                      case SAV_RECORD_SUBTYPE_LONG_STRING_MISSING_VALUES:
  1455                          retval = sav_parse_long_string_missing_values_record(data_buf, size, count, ctx);
  1456                          if (retval != READSTAT_OK)
  1457                              goto cleanup;
  1458                          break;
  1459                      default: /* misc. info */
  1460                          break;
  1461                  }
  1462                  break;
  1463              default:
  1464                  retval = READSTAT_ERROR_PARSE;
  1465                  goto cleanup;
  1466                  break;
  1467          }
  1468          if (done)
  1469              break;
  1470      }

