    23  sav_ctx_t *sav_ctx_init(sav_file_header_record_t *header, readstat_io_t *io) {
    24      sav_ctx_t *ctx = readstat_calloc(1, sizeof(sav_ctx_t));
    25      if (ctx == NULL) {
    26          return NULL;
    27      }
    28
    29      if (memcmp(&header->rec_type, "$FL2", 4) == 0) {
    30          ctx->format_version = 2;
    31      } else if (memcmp(&header->rec_type, "$FL3", 4) == 0) {
    32          ctx->format_version = 3;
    33      } else {
    34          sav_ctx_free(ctx);
    35          return NULL;
    36      }
    37
    38      ctx->bswap = !(header->layout_code == 2 || header->layout_code == 3);
    39      ctx->endianness = (machine_is_little_endian() ^ ctx->bswap) ? READSTAT_ENDIAN_LITTLE : READSTAT_ENDIAN_BIG;
    40
    41      if (header->compression == 1 || byteswap4(header->compression) == 1) {
    42          ctx->compression = READSTAT_COMPRESS_ROWS;
    43      } else if (header->compression == 2 || byteswap4(header->compression) == 2) {
    44          ctx->compression = READSTAT_COMPRESS_BINARY;
    45      }
    46      ctx->record_count = ctx->bswap ? byteswap4(header->ncases) : header->ncases;
    47      ctx->fweight_index = ctx->bswap ? byteswap4(header->weight_index) : header->weight_index;
    48
