            char digit = (fc - '0');
            if (digit >= 0 && digit <= 9) {
                temp_val = 10 * temp_val + digit;
            }
        }

        action save_year {
            if (temp_val < 70) {
                timestamp->tm_year = 100 + temp_val;
            } else {
                timestamp->tm_year = temp_val;
            }
        }

